// 全部Growth TU重编后的域组件；共同动作安装模拟kernel，不冒完整World银行。
#define main original_extended_courses_entry_not_run
#include "extended_growth_courses_test.cpp"
#undef main
#include "resident/domains/growth/growth_study_teaching_requests.hpp"
#include "resident/domains/growth/growth_study_teaching_views.hpp"
namespace {
struct TeacherCourse : Course {
    TeacherCourse():Course("medicine"){
        shared->actor_ids={"student","teacher"};common.state().identity={WorldId{31},4,8,20};common.state().metadata.player_actor_id="teacher";
        shared->roles.insert("student.role",{"student.role","student","school",{},{},{},6});common.state().roles.insert("student.role",{"student",true,{}});
        DialogueDefinition d;d.id="request";d.context_role="student.role";d.entry="ask";DialogueNode n;n.id="ask";n.kind="say";d.nodes.push_back(n);interactions.dialogues.push_back(d);
        InteractionSession session;session.id="meeting";session.actor_id="teacher";session.dialogue_id="request";session.node_id="ask";session.phase="say";session.context={"school","student","student.role"};interaction.interactions.push_back(session);
        catalog.study_teaching_requests.enabled=true;catalog.study_teaching_requests.definitions.insert("request.medicine",{"request.medicine","teacher","student","medicine","teacher.role","request","ask",2,"student_personal_tuition_v1","ordinary_next_level_v1"});
        access.study_teaching_request=[this](const StableId& teacher,const StableId& student,const StableId& skill,Integer duration){return preview_growth_study_teaching_source(read(),catalog.study_teaching_requests,teacher,student,skill,duration);};
        access.revalidate_study_teaching_request=[this](const GrowthStudyTeachingRequestSource& source){return revalidate_growth_study_teaching_source(read(),catalog.study_teaching_requests,source);};
        access.validate_study_teaching_agreement=[this](const GrowthStudyTeachingAgreement& source,const StudyTerms& terms){return validate_growth_study_teaching_agreement(common,*shared,catalog,interactions,catalog.study_teaching_requests,source,terms);};
    }
    GrowthStudyTeachingRead read()const{return {common,growth,catalog,*shared,social,access,interaction,interactions,contact};}
    GrowthCommand teaching()const{GrowthCommand c;c.kind="teach_study";c.skill_id="medicine";c.ticks=2;c.context=InteractionContext{"school","student","student.role"};return c;}
    Outcome<GrowthQuote> quote()const{return preview_growth(common,growth,catalog,*shared,social,access,"teacher",teaching());}
    StableId teach(){auto q=take(quote());auto admission=take(prepare_growth_start(common,catalog,access,"teacher",q));check(bool(admission)&&bool(admission->study_agreement),"student source admitted before either participant is occupied");
        ActionCoreView action;action.id=take(common.next_id("action"));action.kind="teach_study";action.actor_id="teacher";action.participants={"teacher","student"};action.start_tick=common.tick();action.remaining_ticks=2;good(common.apply_action({ActionMutation::Kind::insert,action,{}}));for(const auto& person:action.participants){ActorMutation m;m.actor_id=person;m.action_id=action.id;good(common.apply_actor(m));}
        good(start_growth(common,growth,catalog,*shared,social,access,action,q,&*admission));good(validate_growth(common,growth,catalog,*shared,access));return action.id;
    }
    GrowthEffect control(const StableId& id,const StableId& kind){GrowthCommand c;c.kind=kind;c.action_id=id;auto q=take(preview_growth(common,growth,catalog,*shared,social,access,"teacher",c));auto effect=take(apply_growth_instant(common,growth,catalog,*shared,social,access,"teacher",q));if(kind=="study_cancel")release(id);good(validate_growth(common,growth,catalog,*shared,access));return effect;}
    void cold(){
        auto before=encode_growth_state(growth,false,false,false,true);CodecVisitor::Buffer bytes;CodecVisitor w(bytes);w.schema_features=common_checkpoint::study_teaching_request_sources;good(visit_growth_checkpoint(w,growth));good(w.finish());GrowthState restored;CodecVisitor r(static_cast<const CodecVisitor::Buffer&>(bytes));r.schema_features=common_checkpoint::study_teaching_request_sources;good(visit_growth_checkpoint(r,restored));good(r.finish());check(compare_boundary(before,encode_growth_state(restored,false,false,false,true)).exact(),"teacher request, original student terms and exact ordered history survive typed cold");growth=std::move(restored);good(validate_growth(common,growth,catalog,*shared,access));
        auto seed=encode_common_state(common.state());*seed.find("facts")=*before.find("facts");
        for(auto& row:*seed.find("actions")->as<BoundaryValue::Dict>()){const auto* params=before.find("action_params")->find(row.first);if(params)row.second.as<BoundaryValue::Dict>()->emplace_back("params",*params);}
        auto decoded=take(decode_growth_seed(seed,false,false,false,true));check(compare_boundary(before,encode_growth_state(decoded,false,false,false,true)).exact(),"JSON source and teacher action reconstruct without turning teacher into student");good(validate_growth(common,decoded,catalog,*shared,access));
    }
};
void completion(){TeacherCourse c;auto id=c.teach();check(c.xp()==80&&c.common.wallet("student.wallet")->balance==1000&&growth::reserved(c.common.wallet("student.wallet"),id)==60,"start reserves original student fee without instant XP or transfer");
    check(std::get<StudyFact>(*c.growth.facts.find(id)).actor_id=="student"&&c.common.action(id)->actor_id=="teacher","student learning identity differs from teacher action initiator");c.step(id);check(c.xp()==100&&c.common.wallet("student.wallet")->balance==970&&c.common.wallet("teacher.wallet")->balance==30,"one real teacher lesson pays30 once and grows student20");
    c.interaction.interactions.clear();++c.common.state().identity.execution_epoch;c.cold();auto end=c.step(id);check(end.success&&c.xp()==120&&end.fee_paid==60&&end.xp_gained==40&&c.common.wallet("teacher.wallet")->balance==60,"cold continuation needs actual teacher contact but not the old invitation session");c.cold();
    auto page=take(growth_study_teaching_view(c.common,c.growth,c.catalog,*c.shared,c.social,c.access,"teacher",std::nullopt,0));check(boundary::array(boundary::field(page,"history","page"),"history").size()==1,"teacher sees own unique completed course");check(!growth_study_teaching_view(c.common,c.growth,c.catalog,*c.shared,c.social,c.access,"student",std::nullopt,0).ok,"teacher projection cannot expose another actor page");
    InteractionSession session;session.id="meeting";session.actor_id="teacher";session.dialogue_id="request";session.node_id="ask";session.phase="say";session.context={"school","student","student.role"};c.interaction.interactions.push_back(session);auto repeat=c.quote();check(!repeat.ok&&repeat.error.original.code=="StudyTeachingRequestConsumed","one finite student request cannot be charged twice from the same session node");
}
void pause_and_cancel(){TeacherCourse c;auto id=c.teach();c.step(id);c.control(id,"study_pause");check(c.common.actor("teacher")->action_id.empty()&&c.common.actor("student")->action_id.empty(),"pause releases both genuine participants");c.step(id);c.cold();check(c.xp()==100&&c.common.wallet("teacher.wallet")->balance==30,"paused halfday adds no fee or lesson");c.control(id,"study_resume");check(c.common.action(id)->participants==std::vector<StableId>({"teacher","student"}),"resume restores exact teacher-first action envelope");auto end=c.control(id,"study_cancel");check(end.completed_lessons==1&&end.fee_paid==30&&end.unprovided_released==30&&c.xp()==100,"teacher cancellation retains only actual lesson and releases the unprovided fee");c.cold();const auto wallet_before=encode_common_state(c.common.state());auto denied=c.quote();check(!denied.ok&&denied.error.original.code=="StudyTeachingRequestConsumed"&&compare_boundary(wallet_before,encode_common_state(c.common.state())).exact(),"cancelled original student request cannot start another paid course or change any wallet");
    auto duplicate=c.growth;duplicate.facts.insert("duplicate",*duplicate.facts.find(id));auto valid=validate_growth(c.common,duplicate,c.catalog,*c.shared,c.access);check(!valid.ok&&valid.error.original.code=="DuplicateStudyTeachingConsumption","cold history cannot contain two uses of one finite request");}
void corrupt(){TeacherCourse c;auto id=c.teach();auto original=c.growth;std::get<StudyFact>(*c.growth.facts.find(id)).terms.study_teaching_agreement->student_actor_id="teacher";check(!validate_growth(c.common,c.growth,c.catalog,*c.shared,c.access).ok,"cold accepted source cannot swap the person charged");c.growth=original;
    bool rejected=false;try{encode_growth_state(c.growth);}catch(const boundary::DecodeFailure& e){rejected=e.error.original.code=="StudyTeachingCapabilityRequired";}check(rejected,"old JSON profile refuses a new accepted source");CodecVisitor::Buffer bytes;CodecVisitor old(bytes);check(!visit_growth_checkpoint(old,c.growth).ok,"old typed feature writes no implicit optional marker for the new source");
    auto no_source=c.growth;std::get<StudyFact>(*no_source.facts.find(id)).terms.study_teaching_agreement.reset();check(!validate_growth(c.common,no_source,c.catalog,*c.shared,c.access).ok,"teacher action cannot cold-restore as an old student-initiated course");
}
}
int main(){try{completion();pause_and_cancel();corrupt();std::cout<<"STUDY_TEACHING_LIFECYCLE "<<checks<<" checks 0 failures; domain component only\n";return 0;}catch(const std::exception& e){std::cerr<<"STUDY_TEACHING_LIFECYCLE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
